package es.alexcloudweb.nocturne;

import android.Manifest;
import android.content.pm.PackageManager;
import android.os.Build;
import android.os.Bundle;
import com.getcapacitor.BridgeActivity;
import es.alexcloudweb.nocturne.media.NocturneMediaPlugin;
import es.alexcloudweb.nocturne.updates.NocturneUpdatesPlugin;

public class MainActivity extends BridgeActivity {
    // nocturne:notification-permission (generated by scripts/patch-android.mjs)
    private static final int REQUEST_POST_NOTIFICATIONS = 1001;

    @Override
    public void onCreate(Bundle savedInstanceState) {
        registerPlugin(NocturneMediaPlugin.class);
        registerPlugin(NocturneUpdatesPlugin.class);
        super.onCreate(savedInstanceState);
        if (Build.VERSION.SDK_INT >= 33
                && checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED) {
            requestPermissions(new String[] { Manifest.permission.POST_NOTIFICATIONS }, REQUEST_POST_NOTIFICATIONS);
        }
    }
}
